SELECT COUNT(DISTINCT rel.item_id)
FROM bid_apply_item_rel rel
INNER JOIN bid_apply_record rec ON rec.id = rel.apply_id AND rec.del_flag = '0'
WHERE rec.user_id = #{userId}
  AND rec.session_id = #{sessionId}
  AND rec.tenant_id = #{tenantId}
  AND rec.audit_status IN (0, 1)
  AND rel.del_flag = '0'
